<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['owner','branch_manager','inventory_manager']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='menu'; $pageTitle='Menu — Categories & Products'; $bid=branch_id();
function q1(PDO $pdo,string $sql,array $a){ $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchColumn(); }
function qa(PDO $pdo,string $sql,array $a): array { $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchAll(); }

if (is_post()) { verify_csrf(); $act=$_POST['action']??'';
  if($act==='cat_save'){ if(!empty($_POST['id'])) $pdo->prepare('UPDATE categories SET name=?,sort_order=? WHERE id=? AND tenant_id=?')->execute([trim($_POST['name']),(int)$_POST['sort_order'],(int)$_POST['id'],$tid]);
    else $pdo->prepare('INSERT INTO categories(tenant_id,name,sort_order) VALUES(?,?,?)')->execute([$tid,trim($_POST['name']),(int)($_POST['sort_order']??0)]); flash('success','Category saved.'); }
  elseif($act==='cat_delete'){ $pdo->prepare('DELETE FROM categories WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]); flash('success','Category deleted.'); }
  elseif($act==='prod_save'){ $d=[(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']??''),trim($_POST['image_url']??''),(float)$_POST['price'],(float)($_POST['cost']??0),!empty($_POST['track_stock'])?1:0,(float)($_POST['stock_quantity']??0),(float)($_POST['reorder_level']??5),!empty($_POST['is_combo'])?1:0];
    if(!empty($_POST['id'])){ $pdo->prepare('UPDATE products SET category_id=?,name=?,description=?,image_url=?,price=?,cost=?,track_stock=?,stock_quantity=?,reorder_level=?,is_combo=? WHERE id=? AND tenant_id=?')->execute([...$d,(int)$_POST['id'],$tid]); $pid=(int)$_POST['id']; }
    else { $pdo->prepare('INSERT INTO products(tenant_id,category_id,name,description,image_url,price,cost,track_stock,stock_quantity,reorder_level,is_combo,is_available,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,1,NOW())')->execute([$tid,...$d]); $pid=(int)$pdo->lastInsertId(); }
    $pdo->prepare('DELETE FROM product_variations WHERE product_id=? AND tenant_id=?')->execute([$pid,$tid]);
    foreach (array_filter(array_map('trim', explode(',', $_POST['variations']??''))) as $v) { $parts=explode(':', $v); $pdo->prepare('INSERT INTO product_variations(tenant_id,product_id,name,price_delta) VALUES(?,?,?,?)')->execute([$tid,$pid,trim($parts[0]),(float)($parts[1]??0)]); }
    $pdo->prepare('DELETE FROM addons WHERE product_id=? AND tenant_id=?')->execute([$pid,$tid]);
    foreach (array_filter(array_map('trim', explode(',', $_POST['addons']??''))) as $v) { $parts=explode(':', $v); $pdo->prepare('INSERT INTO addons(tenant_id,product_id,name,price) VALUES(?,?,?,?)')->execute([$tid,$pid,trim($parts[0]),(float)($parts[1]??0)]); }
    flash('success','Product saved (with variations & add-ons).'); }
  elseif($act==='toggle'){ $pdo->prepare('UPDATE products SET is_available=1-is_available WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]); flash('success','Availability toggled.'); }
  elseif($act==='prod_delete'){ $pdo->prepare('DELETE FROM products WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]); flash('success','Product deleted.'); }
  redirect('menu.php'); }
$cats=qa($pdo,'SELECT * FROM categories WHERE tenant_id=? ORDER BY sort_order',[$tid]);
$search=trim($_GET['q']??''); $sql='SELECT p.*,c.name cat_name,(SELECT GROUP_CONCAT(CONCAT(v.name,IF(v.price_delta<>0,CONCAT(":",v.price_delta),"")) SEPARATOR ", ") FROM product_variations v WHERE v.product_id=p.id) variations,(SELECT GROUP_CONCAT(CONCAT(a.name,":",a.price) SEPARATOR ", ") FROM addons a WHERE a.product_id=p.id) addons FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=?'; $a=[$tid];
if($search){ $sql.=' AND p.name LIKE ?'; $a[]='%'.$search.'%'; } $rows=qa($pdo,$sql.' ORDER BY c.sort_order,p.name',$a);
$edit=null; if(!empty($_GET['edit'])){ $s=$pdo->prepare('SELECT p.*,(SELECT GROUP_CONCAT(CONCAT(v.name,IF(v.price_delta<>0,CONCAT(":",v.price_delta),"")) SEPARATOR ",") FROM product_variations v WHERE v.product_id=p.id) variations,(SELECT GROUP_CONCAT(CONCAT(a.name,":",a.price) SEPARATOR ",") FROM addons a WHERE a.product_id=p.id) addons FROM products p WHERE p.id=? AND p.tenant_id=?'); $s->execute([(int)$_GET['edit'],$tid]); $edit=$s->fetch(); }
